SELECT Cylinders, MAX(Accelerate) AS maximum_accelerate
FROM cars_data
GROUP BY Cylinders;

SELECT singer.Country, COUNT(*) AS singer_count
FROM singer
GROUP BY singer.Country;

SELECT Name, Country, Age
FROM singer
ORDER BY Age DESC;

SELECT s.Song_Name
FROM singer AS s
WHERE s.Age > (SELECT AVG(s2.Age) FROM singer AS s2);

SELECT Location, COUNT(*) AS shop_count
FROM shop
GROUP BY Location;

SELECT AVG(Age) AS average_age
FROM visitor
WHERE Level_of_membership <= 4;

SELECT COUNT(*) AS visitor_count
FROM visitor
WHERE Age < 30;

SELECT AVG(m.Num_of_Staff) AS average_staff
FROM museum AS m
WHERE m.Open_Year < '2009';

SELECT COUNT(*) AS channel_count
FROM TV_Channel
WHERE Language = 'English';

SELECT first_name, birth_date
FROM players
WHERE country_code = 'USA';
